update public.content_variants set body_id = $json${"type":"scenario","answer":"Minimalkan risiko","options":["Maksimalkan imbal hasil","Minimalkan risiko","Seimbangkan risiko dan imbal hasil","Ikuti kerumunan"],"question":"Sebuah fintech mengubah pengeluaran menjadi permainan dengan imbalan cashback. Pengguna mengeluarkan uang lebih 30%. Analisis mekanisme perilaku. Pilihan mana yang meminimalkan risiko sambil mempertahankan peluang?","difficulty":"advanced","parameters":{"scenario_text":"Sebuah fintech mengubah pengeluaran menjadi permainan dengan imbalan cashback. Pengguna mengeluarkan uang lebih 30%. Analisis mekanisme perilaku."},"explanation":"Dalam skenario ini, meminimalkan risiko mewakili pendekatan yang paling seimbang dan terinformasi dalam pengambilan keputusan keuangan."}$json$::jsonb where body_id = $json${"type":"scenario","answer":"Minimalkan risiko","options":["Maksimalkan imbal hasil","Minimalkan risiko","Seimbangkan risiko dan imbal hasil","Ikuti kerumunan"],"question":"Sebuah fintech mengubah pengeluaran menjadi permainan dengan imbalan cashback. Pengguna mengeluarkan uang lebih 30%. Analisis mekanisme perilaku. Pilihan mana yang meminimalkan risiko sambil mempertahankan peluang?","difficulty":"advanced","parameters":{"scenario_text":"A fintech gamifies spending with cashback rewards. Users overspend by 30%. Analyze the behavioral mechanism."},"explanation":"Dalam skenario ini, meminimalkan risiko mewakili pendekatan yang paling seimbang dan terinformasi dalam pengambilan keputusan keuangan."}$json$::jsonb;
