update public.content_variants set body_id = $json${"type":"spot_mistake","answer":["Kesalahan perjudian","Biaya yang terbenam dalam lotere","Tidak ada rencana keuangan yang nyata","Kesalahan penjudi (angka 'seharusnya')"],"options":["Kesalahan perjudian","Biaya yang terbenam dalam lotere","Tidak ada rencana keuangan yang nyata","Kesalahan penjudi (angka 'seharusnya')","Tidak ada kesalahan","Hanya satu kesalahan kecil"],"question":"Baca pernyataan berikut dan identifikasi kesalahan finansial:\n\nRencana keuangan saya adalah memenangkan lotere. Saya telah menghabiskan Rp 5 juta untuk tiket lotere tahun ini. Saya yakin angka saya akan segera muncul.","difficulty":"beginner","parameters":{"mistake_count":4},"explanation":"Lotere adalah hiburan, bukan rencana keuangan. Kesalahan 'seharusnya' mengabaikan bahwa setiap undian adalah independen."}$json$::jsonb where body_id = $json${"type":"spot_mistake","answer":["Gambling fallacy","Sunk cost in lottery","No real financial plan","Gambler's fallacy (numbers 'due')"],"options":["Kesalahan perjudian","Biaya yang terbenam dalam lotere","Tidak ada rencana keuangan yang nyata","Kesalahan penjudi (angka 'seharusnya')","Tidak ada kesalahan","Hanya satu kesalahan kecil"],"question":"Baca pernyataan berikut dan identifikasi kesalahan finansial:\n\nRencana keuangan saya adalah memenangkan lotere. Saya telah menghabiskan Rp 5 juta untuk tiket lotere tahun ini. Saya yakin angka saya akan segera muncul.","difficulty":"beginner","parameters":{"mistake_count":4},"explanation":"Lotere adalah hiburan, bukan rencana keuangan. Kesalahan 'seharusnya' mengabaikan bahwa setiap undian adalah independen."}$json$::jsonb;
